use std::io::{self, Read, Write};

/// Takes a slice, so it works on a Vec, an array, or part of either.
fn sum(xs: &[i64]) -> i64 {
    let mut s = 0;
    for x in xs {
        s += *x;
    }
    s
}

/// The best sum of any `k` consecutive elements, and where it starts.
fn best_window(xs: &[i64], k: usize) -> Option<(usize, i64)> {
    if k == 0 || k > xs.len() {
        return None;
    }
    let mut best = sum(&xs[0..k]);
    let mut at = 0usize;
    let mut running = best;
    for i in 1..=(xs.len() - k) {
        running = running - xs[i - 1] + xs[i + k - 1];
        if running > best {
            best = running;
            at = i;
        }
    }
    Some((at, best))
}

fn show(out: &mut dyn Write, label: &str, xs: &[i64]) {
    write!(out, "{}", label).unwrap();
    for x in xs {
        write!(out, " {}", x).unwrap();
    }
    writeln!(out).unwrap();
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = match it.next() {
        Some(t) => t.parse().unwrap(),
        None => return,
    };
    let k: usize = it.next().unwrap().parse().unwrap();

    let mut v: Vec<i64> = Vec::new();
    for _ in 0..n {
        v.push(it.next().unwrap().parse().unwrap());
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "whole {}", sum(&v)).unwrap();

    let mid = v.len() / 2;
    let (left, right) = v.split_at(mid);
    writeln!(out, "halves {} {}", sum(left), sum(right)).unwrap();
    show(&mut out, "left", left);
    show(&mut out, "right", right);

    match best_window(&v, k) {
        Some((at, s)) => writeln!(out, "window {} {}", at, s).unwrap(),
        None => writeln!(out, "window none").unwrap(),
    }

    io::stdout().flush().ok();
}
